head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pageSize = 50; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
// 화면 리사이징

scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gNdvNotiYn; // 야간공지여부
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;
    rdo_MKT_ID.setValue(9);
    pnl_NDV_GB.hide(); // 주야간구분 숨김

    //  기간 from~ to  셋팅
    cmb_PeriodTp.setValue('1'); // 일주일전 날짜

    //  선물공시 보고서
    const sbmOptions = {
        id : "sbm_dts_FormCd",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_FormCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !선물공시상세--;
목록검색;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    fn_Search();
} < !선물공시상세--;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.removeAll();
    let url = "";
    const url_cond = "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&FORM_CD=" + txb_FormCd.getValue() + "&FORM_NM=" + txb_FormNm.getValue() + "&LD_MKT_TP=" + rdo_MKT_ID.getValue() + "&NDV_GB=" + rdo_NDV_GB.getValue() + "&ISUR_CD=" + txb_isur_cd.getValue() + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + 'ULDSTF15400.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 본문검색 키워드가 없을때 ... 일반 DB검색
    url = "/DisclosureSearch.do?method=pagingFuturesDsclSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
    dts_DsclList.DataID = encodeURI(url + url_cond);
    dts_DsclList.reset();
    grd_Grid.show("");
};

/**
 * @method
 * @name PageNoCall
 * @description 현재 선택한 페이지번호
 * @param {*} vPageNo vPageNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.PageNoCall = async function(vPageNo) {
    // 현재 선택한 페이지번호
    scwin.vCurrPageNo = vPageNo;
    const sbmOptions = {
        id : "sbm_dts_DsclList",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !선물공시상세검색--;
엑셀다운로드-- > async function() {
    const sbmOptions = {
        id : "sbm_dts_DsclList_excel",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclList_excel=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gNdvNotiYn = dts_DsclList.getCellData(Number(obj), "NDV_NOTI_YN");
    scwin.gAcptNo = dts_DsclList.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.getCellData(Number(obj), "FORM_VER");

    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};

/**
 * @method
 * @name resetParam
 * @description reset Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.resetParam = function() {
    vCurrDate = $c.ut.cGetToday("yyyymmdd"); // 현재날짜

    edt_FromDate.setValue($c.ut.cGetMinusDate2(vCurrDate, 7));
    edt_ToDate.setValue(vCurrDate);
    scwin.setChkValue(chb_Last, false);
    rdo_MKT_ID.setValue(9);
    pnl_NDV_GB.hide(); // 주야간구분 숨김

};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name cmb_PerPage_onselchange
 * @description cmb_PerPage onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_onselchange = function() {
    const vPerPage = $c.cp.valueOfIndex(cmb_PerPage, "VALUE", cmb_PerPage.getSelectedIndex());
    scwin.pageSize = vPerPage;
    // alert(pageSize);

};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = async function() {
    await $c.win.alert(dts_DsclList);
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = async function(rowcount) {
    if (dts_DsclList.errorMsg) {
        await $c.win.alert(dts_DsclList.errorMsg);
    } else {
        // 수정해야될 부분
        // 데이터가 로드 되면 다음 내용을 처리 하도록 한다.
        // 최초 조회인 경우 전체 row cnt를 구한다.

        // alert(vCurrPageNo +"= "+dts_DsclList.NameString(0,"TOTALCNT")+"= "+dts_DsclList.NameString(1,"TOTALCNT"));

        if (scwin.vCurrPageNo === 0) {
            scwin.vCurrPageNo = 1;
            scwin.totalCnt = dts_DsclList.getCellData(0, "TOTALCNT");
        }

        // alert(pageNoCnt +", "+pageSize+", "+totalCnt);
        // 페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
        $c.stf.FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
    }
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    cmb_EmpList.setValue(js_emp_no);
};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description 부서코드에  해당하는 사원을 가져온다.
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    //  부서코드에  해당하는 사원을 가져온다.
    if (scwin.gDepCd === "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_emp.getCellData(row, "dep_cd") === scwin.gDepCd ||
            dts_emp.getCellData(row, "dep_cd") === "") {
            return true;
        } else {
            return false;
        }
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    cmb_TeamList.setValue(js_dep_cd);
};

/**
 * @method
 * @name dts_DsclList_excel_OnLoadCompleted
 * @description dts_DsclList_excel 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_excel_OnLoadCompleted = function(rowcount) {
    $c.data.downloadGridViewExcel(grd_DsclList_excel, {fileName: "선물공시검색  목록", type: "8"});
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description 클릭된 값 변수에 셋팅
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    // 클릭된 값 변수에 셋팅
    scwin.setContnId(row);
    if (colid === "DOC_TITLE") {
        if (scwin.gNdvNotiYn === "Y") {
            // 야간공지 상세조회 팝업 호출
            let url = "/dsclnightnoti/ULDSTF00002.gfm?NDV_NOTI_NO=" + scwin.gAcptNo + "&NOTI_PROCS_STAT_CD=30&POP_GB=R";
            let winTitle = "야간시장 공지 상세보기";
            $c.frame.path("/top").WinOpen("viewer" + scwin.gAcptNo, url, winTitle, 870, 500);
        } else {
            // 2017-11-28 KBoY 비공개 첨부서류 볼 수 없음.
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF15400.xml');
        }
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
};

/**
 * @method
 * @name rdo_MKT_ID_onselchange
 * @description 시장구분이 파생상품인 경우
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_onselchange = function() {
    // 시장구분이 파생상품인 경우
    if (rdo_MKT_ID.getValue() === '3') {
        pnl_NDV_GB.show("");
        rdo_NDV_GB.setValue("A"); // 주야간구분 전체;

    } else {
        pnl_NDV_GB.hide();
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    fn_ExcelDownload();
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Cancel_onclick = function() {
    scwin.resetParam();
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};

/**
 * @method
 * @name txb_FormCd_onblur
 * @description txb_FormCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FormCd_onblur = function() {
    if (txb_FormCd.getValue() === "") {
        txb_FormNm.setValue("");
    }
};

/**
 * @method
 * @name txb_FormNm_onblur
 * @description txb_FormNm 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_FormNm_onblur = function() {
    if (txb_FormNm.getValue() === "") {
        txb_FormCd.setValue("");
    }
};

/**
 * @method
 * @name img_FindForm_onclick
 * @description *** 셋팅할 필드명 정의를 아래처럼 해야함.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_FindForm_onclick = async function() {
    // *** 셋팅할 필드명 정의를 아래처럼 해야함.
    // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
    let url = "/common/ULDSTF91003_FUTURES.gfm";
    let winTitle = "공시제목선택 ";
    await $c.frame.CreateDialogFrame("FORMLIST", url, winTitle, 100, 10, 695, 575, "window");
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    // Grd_com_isur.style.display ="";
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    /*
    if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
    		Grd_com_isur.Focus();
    }else{
    	if (window.event.keyCode ==13){
    		fn_com_Confirm_set();
    	}else{
    		fn_com_isur_nm(window.event.keyCode);
    	}
    }
     */
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearchFuturesOption(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    grd_DsclList_excel.hide();

    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    await scwin.setCode();
    $c.stf.comboCbDataSet(cmb_PerPage);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    $c.cm.fn_com_isur_futures(txb_isur_cd, txb_com_abbrv);

    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_Dscl_Cond",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Dscl_Cond=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
